(() => {
 const el=document.querySelector('#store-trust');if(!el)return;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 fetch('/api/store').then(r=>{if(!r.ok)throw Error();return r.json();}).then(d=>{const labels={warranty:'Garantia e assistência',delivery:'Entrega',pickup:'Retire na loja',payment:'Formas de pagamento',hours:'Horário de atendimento'};const facts=Object.entries(labels).filter(([k])=>d[k]);if(!facts.length&&!d.teamText&&!d.teamPhotos?.length&&!d.reviews?.length)return;el.innerHTML=`<p class="eyebrow dark">PERTO DE VOCÊ</p><h2>Conheça a Up Smart.</h2>${facts.length?`<div class="trust-grid">${facts.map(([k,label])=>`<article><h3>${label}</h3><p>${esc(d[k])}</p></article>`).join('')}</div>`:''}${d.teamText||d.teamPhotos?.length?`<div class="store-team"><h3>Quem está por trás da Up</h3><p>${esc(d.teamText)}</p><div class="team-photos">${(d.teamPhotos||[]).map(src=>`<img src="${esc(src)}" alt="Equipe da Up Smart" loading="lazy" referrerpolicy="no-referrer">`).join('')}</div></div>`:''}${d.reviews?.length?`<div class="store-reviews"><h3>Histórias de quem escolheu a Up</h3><div class="trust-grid">${d.reviews.map(r=>`<figure><blockquote>${esc(r.text)}</blockquote><figcaption>${esc(r.name)}</figcaption></figure>`).join('')}</div></div>`:''}`;el.hidden=false;}).catch(()=>{});
})();
